function [gm, re, cbar] = default_field()
%DEFAULT_FIELD  The default field's normalised zonal C(n, 0) = -Jn/sqrt(2n + 1) (grav.defaultField), degrees 2 to 6 of a 7 x 7
%   row-major matrix with C(0, 0) = 1; its GM [m^3/s^2] and radius [m].
%   returns gm: real[1] (passed a plain number)
%   returns re: real[1] (passed a plain number)
%   returns cbar: real[1][49] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    gm = 0;
    re = 0;
    cbar = zeros(49, 1);
    D__GRAV_DEFAULT_GM = asils.models.gravfield.GRAV_DEFAULT_GM();
    D__GRAV_DEFAULT_J = asils.models.gravfield.GRAV_DEFAULT_J();
    D__GRAV_DEFAULT_RE = asils.models.gravfield.GRAV_DEFAULT_RE();
    gm = D__GRAV_DEFAULT_GM(1);
    re = D__GRAV_DEFAULT_RE(1);
    cbar = zeros(49, 1);
    cbar(1) = 1;
    for k = (0):((5) - 1)
        n = (k + 2);
        h__270 = ((2 * n) + 1);
        if h__270 < 0, h__270 = NaN; else, h__270 = sqrt(h__270); end
        cbar(((n * 7)) + 1) = ((-(D__GRAV_DEFAULT_J((k) + 1))) / h__270);
    end
end
